#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;

const ll N = 2e5 + 5, V = 100, M = V + 5, L = 25;

int n, m, a[N], lst[N], cnt[N], ans[N], st[L][N];
ll pre[2][N], sum[N];
struct node
{
	int l, r;
} b[N];

int query(int l, int r)
{
	int k = __lg(r - l + 1);
	return min(st[k][l], st[k][r - (1 << k) + 1]);
}

void init() {}

void solve()
{
	cin >> n;
	for (int i = 1; i <= n; ++i)
	{
		cin >> a[i];
		pre[0][i] = pre[0][i - 1] + a[i];
	}
	cin >> m;
	for (int i = 1; i <= m; ++i)
		cin >> b[i].l >> b[i].r, lst[i] = b[i].l - 1;
	for (int x = 1; x <= V; ++x)
	{
		for (int i = 1; i <= n; ++i)
		{
			st[0][i] = pre[x & 1][i] = pre[x & 1][i - 1] + (a[i] <= x ? -a[i] : a[i]);
			cnt[i] = cnt[i - 1] + (a[i] == x);
		}
		if (!cnt[n]) continue;
		for (int j = 1; j <= __lg(n); ++j)
		{
			for (int i = 1; i + (1 << j) - 1 <= n; ++i)
				st[j][i] = min(st[j - 1][i], st[j - 1][i + (1 << (j - 1))]);
		}
		for (int i = 1; i <= m; ++i)
		{
			if (cnt[b[i].r] == cnt[lst[i]]) continue;
			int res = b[i].r + 1;
			for (int l = lst[i] + 1, r = b[i].r, mid; l <= r;)
			{
				mid = (l + r) >> 1;
				if (sum[i] + pre[(x & 1) ^ 1][mid - 1] - pre[(x & 1) ^ 1][lst[i]] + query(mid, b[i].r) - pre[x & 1][mid - 1] >= 0)
				{
					res = mid;
					r = mid - 1;
				}
				else
					l = mid + 1;
			}
			sum[i] += pre[(x & 1) ^ 1][res - 1] - pre[(x & 1) ^ 1][lst[i]];
			lst[i] = res - 1;
			ans[i] += cnt[b[i].r] - cnt[lst[i]];
		}
	}
	for (int i = 1; i <= m; ++i)
		cout << ans[i] << endl;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	int _ = 1;
	// cin >> _;
	init();
	while (_--)
		solve();
	return 0;
}
```

