你这版最直接的卡常点是把 `ll st[N][L]` 改成 `int st[L][N]`。你建表时固定 `j` 枚举 `i`，原写法每次访存跨 \(25\times 8=200\) 字节。更大的提速来自你的判定式本身：**每个询问、每个 \(x\) 只需查一次区间最小值，二分可以直接去掉。**

本机 `g++ -O2`，取 \(N=Q=2\times10^5,\ V=100\)，同一份输入对比，输出逐项一致：

| 数据 | 你贴的版本 | 下方版本 |
|---|---:|---:|
| \(a_i\) 均匀随机，随机询问 | 9.448 s | 0.250 s |
| 相同值连续成段，随机询问 | 5.776 s | 0.238 s |

另用独立 DP 核对了 **83,736 个小区间**，全部一致。以上是本地结果，未在线提交。

### 为什么能去掉二分

沿用你的 `lst` 和 `sum`。先假设 `lst` 后所有值为 \(x\) 的位置都取负，算出从第一个 \(x\) 到询问右端点的**最低余额** \(mn\)。如果 \(mn<0\)，需要改成正号的 \(x\) 的个数恰好是

\[
h=\left\lceil\frac{-mn}{2x}\right\rceil .
\]

下界很直接：每改一个 \(x\)，最低点的余额至多增加 \(2x\)。这个下界也能取到，只需把**最靠前的 \(h\) 个 \(x\)** 改成正号：

- 第 \(h\) 个 \(x\) 之前，遇到的 \(x\) 全取正，与上一轮已经合法的方案相同。
- 从第 \(h\) 个 \(x\) 开始，每个前缀都完整增加了 \(2xh\)，最低余额也至少为零。

所以算出 \(h\) 后，直接用出现位置数组跳到第 \(h\) 个 \(x\)，更新 `lst` 和 `sum` 即可。

ST 表也可以缩小。对于当前值 \(x\)，按它的出现位置分段，每段从一个 \(x\) 开始，到下一个 \(x\) 前结束。一次查询包含若干完整段和最右边一个可能不完整的段。完整段查 ST 表，最后一段直接读预处理的 `low[r]`。这样所有值的段数之和只有 \(N\)，总时间为 **\(O(NV+QV+N\log N)\)**。

[完整 C++ 源文件](</C:/Users/605/Documents/Output/P11994-fast-1113/uiro.cpp>)

```cpp
#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

const int N = 2e5 + 5, V = 100, L = 18;

int n, m, a[N], freq[V + 1], pre[N], cnt[N], pos[N], low[N], st[L][N];
struct node
{
	int lst, r, sum, ans;
} b[N];

void solve()
{
	cin >> n;
	for (int i = 1; i <= n; ++i)
		cin >> a[i], ++freq[a[i]];
	cin >> m;
	for (int i = 1; i <= m; ++i)
		cin >> b[i].lst >> b[i].r, --b[i].lst;
	for (int x = 1; x <= V; ++x)
	{
		if (!freq[x]) continue;
		int t = 0, step = 2 * x;
		for (int i = 1; i <= n; ++i)
		{
			pre[i] = pre[i - 1] + (a[i] <= x ? -a[i] : a[i]);
			if (a[i] == x)
				pos[++t] = i, low[i] = pre[i];
			else
				low[i] = min(low[i - 1], pre[i]);
			cnt[i] = t;
		}
		for (int i = 1; i < t; ++i)
			st[0][i] = low[pos[i + 1] - 1];
		for (int j = 1; (1 << j) < t; ++j)
			for (int i = 1; i + (1 << j) <= t; ++i)
				st[j][i] = min(st[j - 1][i], st[j - 1][i + (1 << (j - 1))]);
		for (int i = 1; i <= m; ++i)
		{
			node &q = b[i];
			int l = cnt[q.lst] + 1, r = cnt[q.r];
			if (l > r) continue;
			int mn = low[q.r];
			if (l < r)
			{
				int k = __lg(r - l);
				mn = min(mn, min(st[k][l], st[k][r - (1 << k)]));
			}
			int base = q.sum - pre[q.lst];
			int d = -base - mn, h = 0;
			if (d > 0)
			{
				h = (d + step - 1) / step;
				q.lst = pos[l + h - 1];
				q.sum = base + pre[q.lst] + step * h;
			}
			q.ans += r - l + 1 - h;
		}
	}
	for (int i = 1; i <= m; ++i)
		cout << b[i].ans << endl;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	solve();
	return 0;
}
```

